    const x = sol[k], intro = ci === 0 ? `У ${K[0][1]}, ${K[1][1]} и ${K[2][1]} живут кошка, собака и попугай — у каждого свой.` : ci === 1 ? `${K[0][0]}, ${K[1][0]} и ${K[2][0]} занимаются футболом, плаванием и шахматами — каждый чем-то одним.` : ci === 2 ? `У ${K[0][1]}, ${K[1][1]} и ${K[2][1]} шарики трёх цветов: красный, синий и жёлтый.` : `${K[0][0]}, ${K[1][0]} и ${K[2][0]} едят на завтрак кашу, омлет и блины — каждый своё.`;
