/* --- 10. Рыцари и лжецы --- */
function lgKnights(r){ const NM = r.sample(['Том', 'Ник', 'Сэм', 'Бен', 'Макс', 'Дан'], 2), [A, Bn] = NM, t = r.int(0, 5), ins = Bn + 'ом';
  const TR = ['снег белый', 'у кошки четыре лапы', 'в неделе семь дней', 'рыбы живут в воде', 'после зимы наступает весна', 'у треугольника три угла', 'летом теплее, чем зимой'];
  const FL = ['снег чёрный', 'у кошки пять лап', 'в неделе десять дней', 'рыбы живут на деревьях', 'после зимы наступает осень', 'у квадрата три угла', 'зимой теплее, чем летом'];
  const TY = ['рыцарь', 'лжец', 'нельзя узнать'];
  if (t === 0) { const tru = r() < .5, s = r.pick(tru ? TR : FL); return C(`${A} сказал: «${s[0].toUpperCase() + s.slice(1)}». Кто ${A} — рыцарь или лжец?`, tru ? 'рыцарь' : 'лжец', TY.filter(x => x !== (tru ? 'рыцарь' : 'лжец')), tru ? 'Это правда — значит, сказал рыцарь.' : 'Это неправда — так может сказать только лжец.'); }
  if (t === 1) { const sp = r.pick(['рыцарь', 'лжец']), cl = r.pick(['рыцарь', 'лжец']), b = sp === 'рыцарь' ? cl : cl === 'рыцарь' ? 'лжец' : 'рыцарь';
    return C(`${A} — ${sp}. Он сказал: «${Bn} — ${cl}». Кто ${Bn}?`, b, TY.filter(x => x !== b), sp === 'рыцарь' ? `Рыцарь говорит правду, значит, ${Bn} — ${cl}.` : `Лжец всегда лжёт, значит, на самом деле ${Bn} — не ${cl}, а ${b}.`); }
  if (t === 2) { const bt = r.pick(['рыцарь', 'лжец']), cl = r.pick(['рыцарь', 'лжец']), a = cl === bt ? 'рыцарь' : 'лжец';
    return C(`${Bn} — ${bt}. ${A} сказал: «${Bn} — ${cl}». Кто ${A}?`, a, TY.filter(x => x !== a), cl === bt ? `${A} сказал правду — значит, он рыцарь.` : `${A} сказал неправду — значит, он лжец.`); }
  if (t === 3) { const sp = r.pick(['рыцарь', 'лжец']), act = r.pick([['Я съел все конфеты', 'Съел ли он все конфеты?'], ['Я был в саду', 'Был ли он в саду?'], ['Я видел дракона', 'Видел ли он дракона?'], ['Я разбил вазу', 'Разбил ли он вазу?'], ['Я не брал мяч', 'Брал ли он мяч?']]);
    const neg = /не /.test(act[0]), yes = (sp === 'рыцарь') !== neg ? 'да' : 'нет';
    return C(`${A} — ${sp}. Он сказал: «${act[0]}». ${act[1]}`, yes, ['да', 'нет', 'нельзя узнать'].filter(x => x !== yes), sp === 'рыцарь' ? 'Рыцарь говорит правду — верим его словам.' : 'Лжец всегда лжёт — на самом деле всё наоборот.'); }
  if (t === 4) return B(['Житель острова сказал: «Я рыцарь». Кто он?|нельзя узнать|рыцарь;лжец|Так скажет и рыцарь (это правда), и лжец (он обманывает).', 'Кто из жителей острова может сказать: «Я лжец»?|никто|только рыцарь;только лжец;любой|Рыцарь не скажет неправду о себе, а лжец не скажет правду о себе.', 'Лжеца спросили: «Ты лжец?» Что он ответит?|«Нет»|«Да»;промолчит;«Не знаю»|Правдивый ответ был бы «да», а лжец всегда лжёт.', 'Рыцаря спросили: «Ты лжец?» Что он ответит?|«Нет»|«Да»;промолчит;«Не знаю»|Рыцарь говорит правду: он не лжец.', 'Любого жителя острова спросили: «Ты рыцарь?» Что он ответит?|«Да»|«Нет»;рыцарь — «да», лжец — «нет»;нельзя узнать|Рыцарь честно скажет «да», а лжец соврёт и тоже скажет «да».', 'Лжец сказал: «Сегодня солнечно». Какая сегодня погода?|не солнечно|солнечно;нельзя узнать|Лжец всегда говорит неправду.'])(r);
  const say = r() < .5 ? 'мы оба рыцари' : 'мы оба лжецы';
  if (say === 'мы оба лжецы') return C(`${A} сказал: «Мы с ${ins} оба лжецы». Кто ${A}?`, 'лжец', ['рыцарь', 'нельзя узнать'], 'Рыцарь так сказать не может: он не лжец. Значит, говорит лжец (а его друг на самом деле рыцарь).');
  return C(`${Bn} — лжец. ${A} сказал: «Мы с ${ins} оба рыцари». Кто ${A}?`, 'лжец', ['рыцарь', 'нельзя узнать'], `${Bn} — лжец, значит, слова «мы оба рыцари» — неправда. Неправду говорит лжец.`); }

