/* Ярик, математика и логика: у числовых ответов — правдоподобные неверные варианты (±1, ±2, ±10, переставленные цифры), без нелепых «×10» и «:10» */
function yWrongs(a, r){ const c = [a + 1, a - 1, a + 10, a - 10, a + 2, a - 2]; if (a >= 12 && a < 100 && a % 10 && a % 11) c.push((a % 10) * 10 + Math.floor(a / 10)); const out = []; for (const v of r.shuffle(c)) if (v >= 0 && v !== a && !out.includes(v)) { out.push(v); if (out.length === 3) break; } return out; }
function YN(q, a, e){ return C(q, a, yWrongs(a, U.rng(U.h(q))), e); }
